import 'dotenv/config'
import express from 'express'
import donkiRoutes from './routes/donkiRoutes.js'
const app = express(), PORT = process.env.PORT || 3001
app.disable('x-powered-by')
app.get('/api/health', (_req, res) => res.json({ ok: true }))
app.use('/api/space-weather', donkiRoutes)
app.use('/api', (_req, res) => res.status(404).json({ error: 'Not found.' }))
// Error messages are generated by the service and never contain the API key.
app.use((err, _req, res, _next) => res.status(err.status || 500).json({ error: err.status ? err.message : 'Unexpected server error.' }))
app.listen(PORT, () => console.log(`AstroGuard API on http://localhost:${PORT} · NASA API key configured: ${process.env.NASA_API_KEY && process.env.NASA_API_KEY !== 'YOUR_NASA_API_KEY' ? 'yes' : 'NO (set NASA_API_KEY in .env)'}`))
